# Démarrage sécurisé DG : si une bibliothèque manque, le programme essaie
# de l’installer puis reprend automatiquement.
def _charger_dependances_dg():
    try:
        from flask import Flask, jsonify, request
    except ModuleNotFoundError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "flask"])
        from flask import Flask, jsonify, request

    try:
        import swisseph as swe
    except ModuleNotFoundError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "pyswisseph"])
        import swisseph as swe

    return Flask, jsonify, request, swe

Flask, jsonify, request, swe = _charger_dependances_dg()

app = Flask(__name__)

@app.after_request
def entetes_ipad_sans_cache_dg(reponse):
    """Empêche Safari et l’ancien service worker de conserver une page noire."""
    if request.path in ('/', '/service-worker.js', '/manifest.webmanifest'):
        reponse.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
        reponse.headers['Pragma'] = 'no-cache'
        reponse.headers['Expires'] = '0'
    return reponse

# DG : calcul astronomique autonome avec Swiss Ephemeris.
# Aucun logiciel Stellarium ni commande à distance n’est nécessaire.
PLANETES_SWISS = {
    "Soleil": swe.SUN,
    "Lune": swe.MOON,
    "Mercure": swe.MERCURY,
    "Vénus": swe.VENUS,
    "Mars": swe.MARS,
    "Jupiter": swe.JUPITER,
    "Saturne": swe.SATURN,
    "Uranus": swe.URANUS,
    "Neptune": swe.NEPTUNE,
    "Pluton": swe.PLUTO,
    "Noeud Nord": swe.TRUE_NODE,
}

def convertir_date_heure_dg(date_str, heure_str):
    """Nettoie les valeurs reçues du navigateur et retourne une date valide.

    Corrige notamment le cas où la date arrive sous la forme ``2026-07-10T``
    ou lorsque le champ heure est vide.
    """
    date_str = str(date_str or "").strip()
    heure_str = str(heure_str or "").strip()

    # Si le navigateur a envoyé date + T (ou date + heure) dans le champ date,
    # on garde seulement la partie AAAA-MM-JJ.
    m_date = re.search(r"(\d{4}-\d{2}-\d{2})", date_str)
    date_propre = m_date.group(1) if m_date else datetime.now().strftime("%Y-%m-%d")

    # Accepter HH:MM ou HH:MM:SS. Une heure vide devient minuit.
    m_heure = re.search(r"(\d{1,2}):(\d{2})(?::(\d{2}))?", heure_str)
    if m_heure:
        h = max(0, min(23, int(m_heure.group(1))))
        minute = max(0, min(59, int(m_heure.group(2))))
        seconde = max(0, min(59, int(m_heure.group(3) or 0)))
        heure_propre = f"{h:02d}:{minute:02d}:{seconde:02d}"
    else:
        heure_propre = "00:00:00"

    return datetime.fromisoformat(f"{date_propre}T{heure_propre}")

def norm360(x):
    x = float(x) % 360
    if x < 0:
        x += 360
    return x

# =========================
# DG : ÉVÈNEMENTS FUTURS AUTOMATIQUES
# Calcul interne des phénomènes astronomiques : chaque évènement a sa vraie date et sa vraie heure.
# Le logiciel ne répète plus seulement la date principale dans le tableau des aspects.
# =========================
ASPECTS_EVENTS_DG = [
    (0, "Conjonction"),
    (60, "Sextile"),
    (90, "Carré"),
    (120, "Trigone"),
    (180, "Opposition"),
]

def _niveau_aspect_dg(nom, ecart=0):
    """Couleur DG selon la force réelle de l'aspect.
    60° et 120° = vert.
    90° et 180° = rouge si très serré, jaune si l'écart est plus large.
    0° = rouge si très serré, jaune si moins serré.
    """
    n = (nom or "").lower()
    try:
        e = abs(float(ecart))
    except Exception:
        e = 0
    if "sextile" in n or "trigone" in n:
        return "🟢"
    if e <= 1.0:
        return "🔴"
    return "🟡"

def _commentaire_aspect_dg(nom, ecart=0):
    n = (nom or "").lower()
    try:
        e = abs(float(ecart))
    except Exception:
        e = 0
    if "sextile" in n or "trigone" in n:
        return "Favorable"
    if e <= 1.0:
        return "Fort : à surveiller"
    return "Moyen : surveiller sans panique"

def _angle_diff_dg(a, b):
    d = abs((a - b) % 360)
    return 360 - d if d > 180 else d


# DG — contexte du Livre arabe pour les évènements futurs.
# Les limites suivent le zodiaque réel déjà utilisé dans le logiciel.
SIGNES_GWD_LIVRE_DG = [
    ("Bélier", 29.0), ("Taureau", 54.0), ("Gémeaux", 90.0),
    ("Cancer", 119.0), ("Lion", 139.0), ("Vierge", 174.0),
    ("Balance", 218.0), ("Scorpion", 241.0), ("Sagittaire", 266.0),
    ("Capricorne", 300.0), ("Verseau", 327.0), ("Poissons", 353.0),
]

def _signe_gwd_livre_dg(angle):
    """Retourne le signe GWD et le degré à l'intérieur du signe."""
    a = norm360(angle)
    # Les degrés 0°–28.999° appartiennent à la fin des Poissons dans ce système.
    a_etendu = a + 360.0 if a < SIGNES_GWD_LIVRE_DG[0][1] else a
    signes_etendus = SIGNES_GWD_LIVRE_DG + [("Bélier", SIGNES_GWD_LIVRE_DG[0][1] + 360.0)]
    for i, (nom, debut) in enumerate(signes_etendus[:-1]):
        fin = signes_etendus[i + 1][1]
        debut_etendu = debut
        if nom == "Poissons" and a_etendu < debut_etendu:
            a_etendu += 360.0
        if debut_etendu <= a_etendu < fin:
            return nom, a_etendu - debut_etendu
    return "Poissons", a_etendu - 353.0

def _maison_depuis_cusps_livre_dg(angle, cusps):
    """Détermine la maison 1–12 à partir des cuspides Placidus."""
    if not cusps or len(cusps) < 12:
        return None
    a = norm360(angle)
    for i in range(12):
        debut = norm360(cusps[i])
        fin = norm360(cusps[(i + 1) % 12])
        largeur = (fin - debut) % 360.0
        distance = (a - debut) % 360.0
        if distance < largeur or abs(distance - largeur) < 1e-9:
            return i + 1
    return None

def _periode_jour_nuit_livre_dg(dt):
    """Secte pratique selon l'heure locale choisie dans le logiciel."""
    return "jour" if 6 <= int(dt.hour) < 18 else "nuit"

def _positions_swiss_dg(dt, lat, lon, tz):
    heure_decimal = dt.hour + dt.minute / 60 + dt.second / 3600
    jd = swe.julday(dt.year, dt.month, dt.day, heure_decimal - tz)
    # DG : Stellarium affiche par défaut les positions depuis le lieu réel
    # de l'observateur (topocentrique). Pour la Lune, la parallaxe peut
    # déplacer la longitude de presque 1 degré. Sans FLG_TOPOCTR, Swiss
    # Ephemeris renvoie une position géocentrique différente de Stellarium.
    swe.set_topo(lon, lat, 0.0)
    # Position topocentrique pour correspondre au ciel observé depuis le lieu choisi.
    flags_position = swe.FLG_SWIEPH | swe.FLG_SPEED | swe.FLG_TOPOCTR
    # Vitesse géocentrique orbitale en degrés/jour. Ne pas utiliser la vitesse
    # topocentrique pour la Lune : la parallaxe quotidienne peut la gonfler artificiellement.
    flags_vitesse = swe.FLG_SWIEPH | swe.FLG_SPEED
    out = {}
    vitesses = {}
    for nom, pcode in PLANETES_SWISS.items():
        try:
            pos, ret = swe.calc_ut(jd, pcode, flags_position)
            pos_vitesse, _ = swe.calc_ut(jd, pcode, flags_vitesse)
            out[nom] = norm360(pos[0])
            vitesses[nom] = float(pos_vitesse[3]) if len(pos_vitesse) > 3 else 0.0
        except Exception:
            pass
    out["__vitesses__"] = vitesses
    # DG : on remet le Noeud Sud automatiquement à 180° du Noeud Nord.
    # Important : les aspects restent calculés uniquement sur 0°, 60°, 90°, 120°, 180°.
    if "Noeud Nord" in out:
        out["Noeud Sud"] = norm360(out["Noeud Nord"] + 180)

    # Angles utiles
    try:
        cusps, ascmc = swe.houses(jd, lat, lon, b"P")
        asc = norm360(ascmc[0]); mc = norm360(ascmc[1])
        out["Ascendant"] = asc
        out["MC"] = mc
        out["Descendant"] = norm360(asc + 180)
        out["FC"] = norm360(mc + 180)
        # Clé interne : utilisée seulement par /events pour calculer les maisons.
        out["__cusps__"] = tuple(float(x) for x in cusps)
    except Exception:
        pass
    return out

@app.route("/events")
def events_route():
    """Calcule les phénomènes comme un logiciel d'observation du ciel.

    Correction DG importante :
    - la colonne « Séparation » est maintenant la vraie distance angulaire sur
      la sphère céleste (ascension droite + déclinaison topocentriques) ;
    - conjonction/opposition = minimum/maximum réel de séparation, comme dans
      la fenêtre « Phénomènes » de Stellarium ;
    - sextile/carré/trigone = passage réel par 60°/90°/120° ;
    - raffinement final à la seconde, sans arrondi artificiel à 0,01°.
    """
    import math

    date_str = request.args.get("date", "2026-07-09")
    heure_str = request.args.get("heure", "00:00:00")
    lat = float(request.args.get("lat", "5.3599"))
    lon = float(request.args.get("lon", "-4.0083"))
    tz = float(request.args.get("tz", "0"))
    jours = max(1, min(365, int(float(request.args.get("jours", "15")))))
    orbe = max(0.1, min(10.0, float(request.args.get("orbe", "5"))))
    planete_filtre = request.args.get("planete", "").strip()

    try:
        debut = convertir_date_heure_dg(date_str, heure_str)
    except Exception:
        debut = datetime(2026, 7, 9, 0, 0, 0)
    fin = debut + timedelta(days=jours)

    objets = [
        "Soleil", "Lune", "Mercure", "Vénus", "Mars", "Jupiter", "Saturne",
        "Uranus", "Neptune", "Pluton", "Noeud Nord", "Noeud Sud"
    ]
    if planete_filtre and planete_filtre in objets:
        paires = [(planete_filtre, x) for x in objets if x != planete_filtre]
    else:
        paires = [(objets[i], objets[j]) for i in range(len(objets)) for j in range(i + 1, len(objets))]

    # Cache : une date n'est calculée qu'une seule fois.
    cache_ciel = {}

    def ciel(dt):
        cle = int(round(dt.timestamp()))
        if cle in cache_ciel:
            return cache_ciel[cle]
        heure_decimal = dt.hour + dt.minute / 60.0 + dt.second / 3600.0
        jd = swe.julday(dt.year, dt.month, dt.day, heure_decimal - tz)
        swe.set_topo(lon, lat, 0.0)
        flags_lon = swe.FLG_SWIEPH | swe.FLG_SPEED | swe.FLG_TOPOCTR
        flags_eq = swe.FLG_SWIEPH | swe.FLG_EQUATORIAL | swe.FLG_TOPOCTR
        donnees = {"__jd__": jd, "__vitesses__": {}, "__vecteurs__": {}}
        for nom, code in PLANETES_SWISS.items():
            try:
                xx, _ = swe.calc_ut(jd, code, flags_lon)
                eq, _ = swe.calc_ut(jd, code, flags_eq)
                donnees[nom] = norm360(xx[0])
                # Vitesse orbitale géocentrique : station directe/rétrograde stable.
                vg, _ = swe.calc_ut(jd, code, swe.FLG_SWIEPH | swe.FLG_SPEED)
                donnees["__vitesses__"][nom] = float(vg[3])
                ra = math.radians(float(eq[0])); dec = math.radians(float(eq[1]))
                donnees["__vecteurs__"][nom] = (
                    math.cos(dec) * math.cos(ra),
                    math.cos(dec) * math.sin(ra),
                    math.sin(dec),
                )
            except Exception:
                pass
        if "Noeud Nord" in donnees:
            donnees["Noeud Sud"] = norm360(donnees["Noeud Nord"] + 180.0)
            # Antipode exact du nœud nord sur la sphère céleste.
            v = donnees["__vecteurs__"].get("Noeud Nord")
            if v:
                donnees["__vecteurs__"]["Noeud Sud"] = (-v[0], -v[1], -v[2])
        try:
            cusps, ascmc = swe.houses(jd, lat, lon, b"P")
            donnees["Ascendant"] = norm360(ascmc[0])
            donnees["MC"] = norm360(ascmc[1])
            donnees["Descendant"] = norm360(ascmc[0] + 180.0)
            donnees["FC"] = norm360(ascmc[1] + 180.0)
            donnees["__cusps__"] = tuple(float(x) for x in cusps)
        except Exception:
            pass
        cache_ciel[cle] = donnees
        return donnees

    def separation(dt, p1, p2):
        d = ciel(dt)
        v1 = d.get("__vecteurs__", {}).get(p1)
        v2 = d.get("__vecteurs__", {}).get(p2)
        if not v1 or not v2:
            # Repli uniquement si un objet ne fournit pas de coordonnées équatoriales.
            return _angle_diff_dg(d.get(p1, 0.0), d.get(p2, 0.0))
        produit = max(-1.0, min(1.0, v1[0]*v2[0] + v1[1]*v2[1] + v1[2]*v2[2]))
        return math.degrees(math.acos(produit))

    def bissection(p1, p2, cible, a, b):
        fa = separation(a, p1, p2) - cible
        fb = separation(b, p1, p2) - cible
        # Raffinement jusqu'à environ une seconde.
        for _ in range(32):
            if (b - a).total_seconds() <= 1.0:
                break
            m = a + (b - a) / 2
            fm = separation(m, p1, p2) - cible
            if fa == 0 or fa * fm <= 0:
                b, fb = m, fm
            else:
                a, fa = m, fm
        return a + (b - a) / 2

    def extremum(p1, p2, a, b, maximum=False):
        # Recherche ternaire robuste sur une petite fenêtre entourant l'extremum.
        for _ in range(44):
            if (b - a).total_seconds() <= 1.0:
                break
            tiers = (b - a) / 3
            m1, m2 = a + tiers, b - tiers
            s1, s2 = separation(m1, p1, p2), separation(m2, p1, p2)
            if maximum:
                if s1 < s2: a = m1
                else: b = m2
            else:
                if s1 > s2: a = m1
                else: b = m2
        return a + (b - a) / 2

    pas_minutes = 20 if jours <= 31 else 60
    echantillons = []
    dt = debut
    while dt <= fin:
        echantillons.append(dt)
        dt += timedelta(minutes=pas_minutes)
    if echantillons[-1] < fin:
        echantillons.append(fin)

    candidats = []
    # Stations direct/rétrograde.
    vitesses_prec = {}
    for dt in echantillons:
        vit = ciel(dt).get("__vitesses__", {})
        for nom, v in vit.items():
            if nom in ("Soleil", "Lune", "Noeud Nord"):
                vitesses_prec[nom] = (dt, v); continue
            if planete_filtre and nom != planete_filtre:
                vitesses_prec[nom] = (dt, v); continue
            prec = vitesses_prec.get(nom)
            if prec and ((prec[1] >= 0 > v) or (prec[1] <= 0 < v)):
                # Bisection de la vitesse géocentrique autour de zéro.
                a, b = prec[0], dt
                for _ in range(32):
                    if (b-a).total_seconds() <= 1: break
                    m = a + (b-a)/2
                    vm = ciel(m).get("__vitesses__", {}).get(nom, 0.0)
                    if prec[1] * vm <= 0: b = m
                    else: a = m; prec = (m, vm)
                evt = a + (b-a)/2
                nom_evt = "Rétrograde" if v < 0 else "Retour direct"
                candidats.append({"type":"station", "datetime":evt, "point1":nom, "point2":"—", "aspect":nom_evt})
            vitesses_prec[nom] = (dt, v)

    # Phénomènes angulaires.
    # RÈGLE DG : dès qu'un Nœud Nord/Sud est concerné, seule la CONJONCTION
    # est conservée. Aucun carré, sextile, trigone ou opposition avec un nœud.
    noeuds_dg = {"Noeud Nord", "Noeud Sud"}
    for p1, p2 in paires:
        touche_noeud = p1 in noeuds_dg or p2 in noeuds_dg
        # Le Nœud Nord et le Nœud Sud sont antipodaux : ne pas créer
        # un phénomène artificiel entre eux.
        if p1 in noeuds_dg and p2 in noeuds_dg:
            continue
        vals = [separation(x, p1, p2) for x in echantillons]
        # Conjonction = minimum local.
        for i in range(1, len(echantillons)-1):
            if vals[i] <= vals[i-1] and vals[i] <= vals[i+1] and vals[i] <= orbe:
                evt = extremum(p1, p2, echantillons[i-1], echantillons[i+1], maximum=False)
                candidats.append({"type":"aspect", "datetime":evt, "point1":p1, "point2":p2, "aspect":"Conjonction", "angle_cible":0.0})
            # Opposition seulement entre les vraies planètes, jamais avec les nœuds.
            if (not touche_noeud) and vals[i] >= vals[i-1] and vals[i] >= vals[i+1] and (180.0-vals[i]) <= orbe:
                evt = extremum(p1, p2, echantillons[i-1], echantillons[i+1], maximum=True)
                candidats.append({"type":"aspect", "datetime":evt, "point1":p1, "point2":p2, "aspect":"Opposition", "angle_cible":180.0})
        # Sextile, carré et trigone seulement entre les vraies planètes.
        if touche_noeud:
            continue
        for cible, nom in ((60.0,"Sextile"),(90.0,"Carré"),(120.0,"Trigone")):
            for i in range(len(echantillons)-1):
                f1, f2 = vals[i]-cible, vals[i+1]-cible
                if f1 == 0 or f1*f2 < 0:
                    evt = bissection(p1, p2, cible, echantillons[i], echantillons[i+1])
                    candidats.append({"type":"aspect", "datetime":evt, "point1":p1, "point2":p2, "aspect":nom, "angle_cible":cible})

    # Supprimer les doublons à moins de deux minutes pour la même paire/aspect.
    candidats.sort(key=lambda c: c["datetime"])
    uniques = []
    for c in candidats:
        doublon = any(
            u["point1"] == c["point1"] and u["point2"] == c["point2"] and
            u["aspect"] == c["aspect"] and abs((u["datetime"]-c["datetime"]).total_seconds()) < 120
            for u in uniques[-20:]
        )
        if not doublon:
            uniques.append(c)

    events = []
    for cand in uniques:
        dt = cand["datetime"].replace(microsecond=0)
        pos = ciel(dt)
        p1, p2, nom = cand["point1"], cand["point2"], cand["aspect"]
        pos1 = float(pos.get(p1, 0.0)) % 360.0
        pos2 = float(pos.get(p2, 0.0)) % 360.0 if p2 != "—" else 0.0
        sep = separation(dt, p1, p2) if p2 != "—" else 0.0
        cible = float(cand.get("angle_cible", sep))
        ecart = abs(sep-cible)
        signe1, deg1 = _signe_gwd_livre_dg(pos1)
        signe2, deg2 = (_signe_gwd_livre_dg(pos2) if p2 != "—" else ("—", 0.0))
        cusps = pos.get("__cusps__")
        m1 = _maison_depuis_cusps_livre_dg(pos1, cusps)
        m2 = _maison_depuis_cusps_livre_dg(pos2, cusps) if p2 != "—" else None

        def horizon(nom_objet):
            if nom_objet in ("—", "Noeud Sud"):
                return None, None
            code = PLANETES_SWISS.get(nom_objet)
            if code is None:
                return None, None
            try:
                swe.set_topo(lon, lat, 0.0)
                xx, _ = swe.calc_ut(pos["__jd__"], code, swe.FLG_SWIEPH | swe.FLG_EQUATORIAL | swe.FLG_TOPOCTR)
                hor = swe.azalt(pos["__jd__"], swe.EQU2HOR, (lon, lat, 0.0), 0.0, 15.0, (xx[0], xx[1], xx[2]))
                return float(hor[0]), float(hor[1])
            except Exception:
                return None, None
        az1, h1 = horizon(p1); az2, h2 = horizon(p2)

        eclipse = None
        if p2 != "—" and {p1, p2} == {"Soleil", "Lune"}:
            noeud = pos.get("Noeud Nord")
            lune_pos = pos1 if p1 == "Lune" else pos2
            pres = noeud is not None and min(_angle_diff_dg(lune_pos, noeud), _angle_diff_dg(lune_pos, norm360(noeud+180))) <= 18
            if pres and nom == "Conjonction": eclipse = "Éclipse solaire"
            if pres and nom == "Opposition": eclipse = "Éclipse lunaire"

        soleil = float(pos.get("Soleil", 0.0))
        events.append({
            "date": dt.strftime("%Y-%m-%d"), "heure": dt.strftime("%H:%M:%S"),
            "point1": p1, "point2": p2, "aspect": nom, "eclipse": eclipse,
            "position1": round(pos1, 4), "position2": round(pos2, 4),
            "signe1": signe1, "signe2": signe2,
            "degre_signe1": round(deg1, 2), "degre_signe2": round(deg2, 2),
            "maison1": f"Maison {m1}" if m1 else "—", "maison2": f"Maison {m2}" if m2 else "—",
            "periode": _periode_jour_nuit_livre_dg(dt),
            "azimut1": az1, "azimut2": az2, "hauteur1": h1, "hauteur2": h2,
            "elongation1": _angle_diff_dg(pos1, soleil),
            "elongation2": (_angle_diff_dg(pos2, soleil) if p2 != "—" else None),
            "angle": round(sep, 5), "ecart": round(ecart, 5),
            "niveau": "🔴" if "Rétrograde" in nom else ("🟢" if "Retour direct" in nom else _niveau_aspect_dg(nom, ecart)),
            "information": f"{p1} {nom} {p2}".strip()
        })

    events.sort(key=lambda e: (e["date"], e["heure"]))
    return jsonify({"ok": True, "events": events[:500], "debug": {
        "jours": jours, "orbe": orbe, "pas_minutes": pas_minutes,
        "planete": planete_filtre or "TOUTES", "methode": "séparation sphérique topocentrique"
    }})

@app.route("/ascendant-time")
def ascendant_time_route():
    """Trouve automatiquement une heure du jour où l'Ascendant est dans le signe GWD choisi."""
    date_str = request.args.get("date", datetime.now().strftime("%Y-%m-%d"))
    signe_voulu = request.args.get("signe", "").strip()
    lat = float(request.args.get("lat", "5.3599"))
    lon = float(request.args.get("lon", "-4.0083"))
    tz = float(request.args.get("tz", "0"))
    signes_gwd = [
        ("Bélier", 29), ("Taureau", 54), ("Gémeaux", 90), ("Cancer", 119),
        ("Lion", 139), ("Vierge", 174), ("Balance", 218), ("Scorpion", 241),
        ("Sagittaire", 266), ("Capricorne", 300), ("Verseau", 327), ("Poissons", 353),
    ]
    noms = [x[0] for x in signes_gwd]
    if signe_voulu not in noms:
        return jsonify({"ok": False, "error": "Signe invalide"})

    try:
        base = convertir_date_heure_dg(date_str, "00:00:00")
        def signe_de_angle(angle):
            a = norm360(angle)
            # Poissons traverse 360° : 353° à 29°.
            if a >= 353 or a < 29:
                return "Poissons"
            trouve = "Poissons"
            for i, (nom, debut) in enumerate(signes_gwd[:-1]):
                fin = signes_gwd[i + 1][1]
                if debut <= a < fin:
                    trouve = nom
                    break
            return trouve

        minutes_cibles = []
        for minute in range(1440):
            dt = base + timedelta(minutes=minute)
            heure_decimal = dt.hour + dt.minute / 60.0
            jd = swe.julday(dt.year, dt.month, dt.day, heure_decimal - tz)
            _, ascmc = swe.houses(jd, lat, lon, b"P")
            asc = norm360(ascmc[0])
            if signe_de_angle(asc) == signe_voulu:
                minutes_cibles.append((minute, asc))

        if not minutes_cibles:
            return jsonify({"ok": False, "error": "Aucune heure trouvée pour ce signe ce jour-là"})

        # Regrouper les minutes consécutives et choisir le milieu de la plus longue plage.
        groupes = []
        courant = [minutes_cibles[0]]
        for item in minutes_cibles[1:]:
            if item[0] == courant[-1][0] + 1:
                courant.append(item)
            else:
                groupes.append(courant); courant = [item]
        groupes.append(courant)
        groupe = max(groupes, key=len)
        minute, asc = groupe[len(groupe)//2]
        dt = base + timedelta(minutes=minute)
        return jsonify({
            "ok": True, "signe": signe_voulu, "heure": dt.strftime("%H:%M:%S"),
            "ascendant": round(asc, 4), "debut": (base + timedelta(minutes=groupe[0][0])).strftime("%H:%M"),
            "fin": (base + timedelta(minutes=groupe[-1][0])).strftime("%H:%M")
        })
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})


@app.route("/phases_lumieres")
def phases_lumieres_route():
    """Phases lunaires et tendance de lumière des astres visibles.
    Pour la Lune : phase nommée + prochaines Nouvelle Lune, quartiers et Pleine Lune.
    Pour les autres planètes : pourcentage éclairé et tendance (monte/descend).
    """
    try:
        date_str = request.args.get("date", "2026-07-09")
        heure_str = request.args.get("heure", "00:00:00")
        tz = float(request.args.get("tz", "0"))
        d = convertir_date_heure_dg(date_str, heure_str)
        heure_decimal = d.hour + d.minute / 60 + d.second / 3600
        jd = swe.julday(d.year, d.month, d.day, heure_decimal - tz)
        flags = swe.FLG_SWIEPH | swe.FLG_SPEED

        def angle_phase(j):
            lune = swe.calc_ut(j, swe.MOON, flags)[0][0]
            soleil = swe.calc_ut(j, swe.SUN, flags)[0][0]
            return norm360(lune - soleil)

        def illumination_objet(j, code):
            try:
                return float(swe.pheno_ut(j, code, flags)[1]) * 100.0
            except Exception:
                return None

        def phase_lune_nom(angle):
            a = norm360(angle)
            if a < 11.25 or a >= 348.75: return "Nouvelle Lune"
            if a < 78.75: return "Premier croissant"
            if a < 101.25: return "Premier quartier"
            if a < 168.75: return "Lune gibbeuse croissante"
            if a < 191.25: return "Pleine Lune"
            if a < 258.75: return "Lune gibbeuse décroissante"
            if a < 281.25: return "Dernier quartier"
            return "Dernier croissant"

        def prochain_passage(cible):
            # Recherche du prochain franchissement de l'angle cible, puis interpolation.
            pas = 1.0 / 24.0  # une heure
            j0 = jd
            a0 = angle_phase(j0)
            avance0 = norm360(a0 - cible)
            for k in range(1, 24 * 35 + 1):
                j1 = jd + k * pas
                a1 = angle_phase(j1)
                avance1 = norm360(a1 - cible)
                # Le passage se reconnaît par le retour de ~360 vers 0.
                if avance1 < avance0 - 180:
                    lo, hi = j1 - pas, j1
                    for _ in range(28):
                        mid = (lo + hi) / 2
                        am = norm360(angle_phase(mid) - cible)
                        # avant le passage, la valeur est proche de 360
                        if am > 180: lo = mid
                        else: hi = mid
                    return (lo + hi) / 2
                avance0 = avance1
            return None

        def jd_vers_local(j):
            y, m, day, heure = swe.revjul(j + tz / 24.0, swe.GREG_CAL)
            h = int(heure)
            minute_float = (heure - h) * 60
            mi = int(minute_float)
            sec = int(round((minute_float - mi) * 60))
            if sec >= 60: sec, mi = 0, mi + 1
            if mi >= 60: mi, h = 0, h + 1
            dt = datetime(int(y), int(m), int(day)) + timedelta(hours=h, minutes=mi, seconds=sec)
            jours_fr = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"]
            return {
                "jour": jours_fr[dt.weekday()],
                "date": dt.strftime("%d/%m/%Y"),
                "heure": dt.strftime("%H:%M"),
                "iso": dt.strftime("%Y-%m-%dT%H:%M:%S")
            }

        angle = angle_phase(jd)
        illum_lune = illumination_objet(jd, swe.MOON)
        angle_avant = angle_phase(jd - 1.0 / 24.0)
        # différence angulaire signée sur une heure
        delta = ((angle - angle_avant + 540) % 360) - 180
        croissante = 0 < angle < 180

        evenements = []
        for nom, cible in [("Nouvelle Lune", 0), ("Premier quartier", 90), ("Pleine Lune", 180), ("Dernier quartier", 270)]:
            j_evt = prochain_passage(cible)
            if j_evt is not None:
                evt = jd_vers_local(j_evt)
                evt.update({"nom": nom, "angle": cible})
                evenements.append(evt)
        evenements.sort(key=lambda x: x["iso"])

        objets = {}
        codes = {
            "Lune": swe.MOON, "Mercure": swe.MERCURY, "Vénus": swe.VENUS,
            "Mars": swe.MARS, "Jupiter": swe.JUPITER, "Saturne": swe.SATURN,
            "Uranus": swe.URANUS, "Neptune": swe.NEPTUNE, "Pluton": swe.PLUTO,
        }
        for nom, code in codes.items():
            maintenant = illumination_objet(jd, code)
            avant = illumination_objet(jd - 6.0 / 24.0, code)
            apres = illumination_objet(jd + 6.0 / 24.0, code)
            tendance = "Indéterminée"
            variation = None
            if avant is not None and apres is not None:
                variation = apres - avant
                if variation > 0.002: tendance = "Lumière en augmentation"
                elif variation < -0.002: tendance = "Lumière en diminution"
                else: tendance = "Lumière presque stable"
            objets[nom] = {
                "illumination": maintenant,
                "tendance": tendance,
                "variation_12h": variation,
            }

        objets["Lune"].update({
            "phase": phase_lune_nom(angle),
            "angle_phase": angle,
            "cycle": "Croissante" if croissante else "Décroissante",
            "vitesse_phase_horaire": delta,
        })
        return jsonify({"ok": True, "lune": objets["Lune"], "objets": objets, "evenements_lunaires": evenements})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})

@app.route("/stellarium")
def stellarium_route():
    """Compatibilité ancienne interface : utilise désormais le moteur interne.
    Aucun accès réseau ni Stellarium n’est effectué.
    """
    return swiss_route()

@app.route("/swiss")
def swiss_route():
    date_str = request.args.get("date", "2026-07-09")
    heure_str = request.args.get("heure", "00:00:00")
    lat = float(request.args.get("lat", "5.3599"))
    lon = float(request.args.get("lon", "-4.0083"))
    tz = float(request.args.get("tz", "0"))

    planetes = {}
    erreurs = {}

    try:
        d = convertir_date_heure_dg(date_str, heure_str)
        heure_decimal = d.hour + d.minute / 60 + d.second / 3600
        heure_ut = heure_decimal - tz
        jd = swe.julday(d.year, d.month, d.day, heure_ut)
        # Même référentiel que Stellarium : observateur placé au lieu choisi.
        # Cette correction est surtout indispensable pour la Lune.
        swe.set_topo(lon, lat, 0.0)
        flags_position = swe.FLG_SWIEPH | swe.FLG_SPEED | swe.FLG_TOPOCTR
        flags_vitesse = swe.FLG_SWIEPH | swe.FLG_SPEED

        for nom, pcode in PLANETES_SWISS.items():
            try:
                pos, ret = swe.calc_ut(jd, pcode, flags_position)
                pos_vitesse, _ = swe.calc_ut(jd, pcode, flags_vitesse)
                lam = norm360(pos[0])
                beta = float(pos[1])
                # Vitesse orbitale géocentrique réelle en degrés par jour.
                # Elle évite les valeurs topocentriques exagérées comme 19,45°/jour.
                vit = float(pos_vitesse[3])
                illumination = None
                try:
                    if pcode not in [swe.TRUE_NODE, swe.MEAN_NODE]:
                        ph = swe.pheno_ut(jd, pcode, flags_position)
                        illumination = float(ph[1]) * 100
                except Exception:
                    illumination = None
                azimut = None
                hauteur = None
                try:
                    # État réel dans le ciel pour le lieu choisi : azimut + hauteur.
                    # Azimut = direction autour de l’horizon. Hauteur > 0 = visible au-dessus de l’horizon.
                    az = swe.azalt(jd, swe.ECL2HOR, (lon, lat, 0), 0, 15, (lam, beta, pos[2]))
                    azimut = float(az[0])
                    hauteur = float(az[1])
                except Exception:
                    pass
                planetes[nom] = {
                    "lambda": lam,
                    "beta": beta,
                    "illumination": illumination,
                    "vitesse": vit,
                    "etat": "Rétrograde" if vit < 0 else "Direct",
                    "azimut": azimut,
                    "hauteur": hauteur
                }
            except Exception as e:
                erreurs[nom] = str(e)

        if "Noeud Nord" in planetes:
            nn = planetes["Noeud Nord"]
            planetes["Noeud Sud"] = {
                "lambda": norm360(nn["lambda"] + 180),
                "beta": -nn.get("beta", 0),
                "illumination": None,
                "vitesse": nn["vitesse"],
                "etat": nn["etat"],
                "azimut": None,
                "hauteur": None
            }

        cusps, ascmc = swe.houses(jd, lat, lon, b"P")
        asc = norm360(ascmc[0])
        mc = norm360(ascmc[1])

        angles = {
            "Ascendant": {"lambda": asc},
            "MC": {"lambda": mc},
            "Descendant": {"lambda": norm360(asc + 180)},
            "FC": {"lambda": norm360(mc + 180)},
        }

        maisons = []
        # Swiss Ephemeris Python donne les cuspides en liste 0..11
        # Maison 1 = cusps[0], Maison 12 = cusps[11]
        for i in range(12):
            maisons.append({
                "n": i + 1,
                "lambda": norm360(cusps[i])
            })

        return jsonify({
            "ok": True,
            "planetes": planetes,
            "angles": angles,
            "maisons": maisons,
            "errors": erreurs,
            "debug": {
                "asc_tropical_reel": asc,
                "mc_tropical_reel": mc,
                "date": date_str,
                "heure": heure_str,
                "lat": lat,
                "lon": lon,
                "tz": tz
            }
        })

    except Exception as e:
        return jsonify({"ok": False, "planetes": {}, "angles": {}, "errors": {"global": str(e)}})


# =========================
# DG : SAUVEGARDE DURABLE DES RÉGLAGES SUR LE MAC
# Les réglages ne dépendent plus uniquement du localStorage du navigateur.
# Ils sont aussi enregistrés dans ~/Library/Application Support/GWDAMC/reglages.json
# afin de rester identiques après fermeture, redémarrage ou reconstruction de l’application.
# =========================
def _dossier_reglages_gwd_dg():
    if sys.platform == "darwin":
        base = Path.home() / "Library" / "Application Support"
    else:
        base = Path.home() / ".config"
    dossier = base / "GWDAMC"
    dossier.mkdir(parents=True, exist_ok=True)
    return dossier

FICHIER_REGLAGES_GWD_DG = _dossier_reglages_gwd_dg() / "reglages.json"
_verrou_reglages_gwd_dg = threading.RLock()

def _lire_reglages_gwd_dg():
    with _verrou_reglages_gwd_dg:
        try:
            if not FICHIER_REGLAGES_GWD_DG.exists():
                return {}
            data = json.loads(FICHIER_REGLAGES_GWD_DG.read_text(encoding="utf-8"))
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}

def _ecrire_reglages_gwd_dg(data):
    if not isinstance(data, dict):
        raise ValueError("Format de réglages invalide")
    with _verrou_reglages_gwd_dg:
        FICHIER_REGLAGES_GWD_DG.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp_name = tempfile.mkstemp(prefix="reglages_", suffix=".json", dir=str(FICHIER_REGLAGES_GWD_DG.parent))
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_name, FICHIER_REGLAGES_GWD_DG)
        finally:
            if os.path.exists(tmp_name):
                try:
                    os.remove(tmp_name)
                except OSError:
                    pass

@app.route("/gwd-settings", methods=["GET", "POST"])
def reglages_persistants_gwd_dg():
    if request.method == "GET":
        return jsonify({"ok": True, "settings": _lire_reglages_gwd_dg(), "path": str(FICHIER_REGLAGES_GWD_DG)})
    try:
        payload = request.get_json(silent=True) or {}
        settings = payload.get("settings", payload)
        if not isinstance(settings, dict):
            return jsonify({"ok": False, "erreur": "Réglages invalides"}), 400
        _ecrire_reglages_gwd_dg(settings)
        return jsonify({"ok": True, "path": str(FICHIER_REGLAGES_GWD_DG)})
    except Exception as exc:
        return jsonify({"ok": False, "erreur": str(exc)}), 500

@app.route("/gwd-settings/reset", methods=["POST"])
def reinitialiser_reglages_persistants_gwd_dg():
    try:
        with _verrou_reglages_gwd_dg:
            if FICHIER_REGLAGES_GWD_DG.exists():
                FICHIER_REGLAGES_GWD_DG.unlink()
        return jsonify({"ok": True})
    except Exception as exc:
        return jsonify({"ok": False, "erreur": str(exc)}), 500

